declare
  target_page constant text := 'page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f';
  previous_blocks constant jsonb := '[{"position":0,"block_type":"paragraph","text":"באתר roniellatours.com נעשו מאמצים להנגיש את תכני האתר לכלל האוכלוסייה בהתאם לרמה הנגישות הקבועה בחוק.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":1,"block_type":"heading","text":"מהו אתר נגיש?","heading_level":2,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":2,"block_type":"paragraph","text":"אתר שמוגדר “נגיש” אמור לספק חווית גלישה נעימה ונוחה לכולם. מדובר על אתר ידידותי, זמין 24 שעות ביממה לשימוש עבור אנשים עם מוגבלויות, לקויות ואנשים המתקשים בהפעלת המחשב והאינטרנט.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":3,"block_type":"paragraph","text":"אתר נגיש מאפשר לכלל הגולשים לגלוש בנוחות ובמהירות וליהנות מהתכנים והשירותים המוצעים באתר בצורה הטובה ביותר.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":4,"block_type":"paragraph","text":"האתר נבנה בהתאם להוראות הנגישות המופיעות ב –W3C’s Web Content Accessibility Guidelines 2.0, level AA","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":5,"block_type":"heading","text":"שימוש בתפריט הנגישות","heading_level":2,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":6,"block_type":"paragraph","text":"אנחנו משתמשים בכלי הנגשת אתרים מבית CODE IN ROL","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":7,"block_type":"paragraph","text":"בלחיצה על הכפתור יפתח תפריט נגישות עם כלי עזר שונים:","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":8,"block_type":"heading","text":"מה ניתן לשנות?","heading_level":3,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":9,"block_type":"list","text":null,"heading_level":null,"anchor_ids":[],"links":[],"list_ordered":false,"list_items":[{"text":"ניווט במקלדת","links":[],"children":[]},{"text":"ביטול הבהובים ואנימציות","links":[],"children":[]},{"text":"שינוי ניגודיות (כהה / בהירה)","links":[],"children":[]},{"text":"הגדלת טקסט","links":[],"children":[]},{"text":"הקטנת טקסט","links":[],"children":[]},{"text":"שינוי לגופן קריא יותר","links":[],"children":[]},{"text":"סימון כותרות","links":[],"children":[]},{"text":"סימון קישורים ולחצנים","links":[],"children":[]}],"table_caption":null,"table_rows":null},{"position":10,"block_type":"heading","text":"מערכות הפעלה ודפדפנים","heading_level":2,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":11,"block_type":"paragraph","text":"כתובת האתר והדפים השונים הקשורים לדומיין www.shimara.co.il נבדקו במערכות הפעלה Windows ו OSX בדפדפנים: אדג’, כרום ודפדפן Firefox בגרסאות האחרונות.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":12,"block_type":"heading","text":"דיווח על תוכן לא נגיש","heading_level":2,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":13,"block_type":"paragraph","text":"אנו עושים את מירב המאמצים להציג אתר נגיש שנדרש על פי חוק, ייתכן וחלק מהדפים יהיו פחות נגישים. במידה ומצאתם עמוד שאינו נגיש נשמח אם תשלחו למנהל אחסון האתר פנייה ישירה למייל בכתובת roniellatours@gmail.com","heading_level":null,"anchor_ids":[],"links":[{"text":"roniellatours@gmail.com","href":"mailto:roniellatours@gmail.com"}],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":14,"block_type":"paragraph","text":"יש לציין את העמוד כולל קישור ישיר על מנת שנוכל לבדוק ברצינות את הפניה, צרו קשר ונפעל לבצע התאמות במידת הצורך לפי יכולתנו.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":15,"block_type":"paragraph","text":"הצהרה זאת עודכנה לאחרונה בתאריך: 7/4/24.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null}]'::jsonb;
  replacement_blocks constant jsonb := '[{"position":0,"block_type":"paragraph","text":"אנחנו פועלים להנגיש את אתר טיולי העולם העתיק כדי לאפשר לאנשים עם מוגבלות לקבל מידע על המסעות וליצור איתנו קשר. ההתאמות מפותחות ונבדקות בהתייחס לתקן הישראלי ת״י 5568 חלק 1, מהדורת ספטמבר 2023, המבוסס על הנחיות W3C WCAG 2.0 ברמת AA ובכפוף לשינויים הישראליים בתקן. בדיקות הנגישות עדיין נמשכות; טרם הושלמה הערכת התאמה מלאה, ולכן איננו מצהירים בשלב זה על עמידה מלאה בתקן.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":1,"block_type":"heading","text":"אפשרויות שימוש באתר","heading_level":2,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":2,"block_type":"list","text":null,"heading_level":null,"anchor_ids":[],"links":[],"list_ordered":false,"list_items":[{"text":"ניווט באמצעות Tab ו־Shift+Tab, הפעלת קישורים באמצעות Enter והפעלת כפתורים באמצעות Enter או רווח.","links":[],"children":[]},{"text":"קישור דילוג לתוכן הראשי, כותרות מסודרות, תוויות לשדות הטופס וחיווי לשגיאות.","links":[],"children":[]},{"text":"פתיחה וסגירה של פירוט מסלולי הטיולים באמצעות המקלדת; מידע מרכזי וניווט זמינים גם ללא JavaScript.","links":[],"children":[]},{"text":"הגדלת תצוגה באמצעות כלי הדפדפן. אין צורך להפעיל תפריט מיוחד כדי לנווט במקלדת.","links":[],"children":[]}],"table_caption":null,"table_rows":null},{"position":3,"block_type":"heading","text":"התאמות תצוגה בתפריט הנגישות","heading_level":2,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":4,"block_type":"paragraph","text":"באתר משולב כלי הקוד הפתוח Accessibility מאת Ran Buchnik, ברישיון MIT. כפתור עם סמל נגישות מופיע בפינה השמאלית התחתונה. התפריט מאפשר שינוי גודל טקסט, ריווח טקסט ושורות, היפוך צבעים, גווני אפור, הדגשת קישורים, סמן מוגדל, מדריך קריאה ועצירת אנימציות. אפשר לסגור את התפריט באמצעות כפתור הסגירה או Escape, ולאפס את ההתאמות באמצעות כפתור האיפוס. חלק מההעדפות נשמרות בדפדפן במכשיר שבו בחרתם אותן. אם שמירת העדפות חסומה בדפדפן, ההתאמות יפעלו בביקור הנוכחי בלבד.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":5,"block_type":"paragraph","text":"התפריט מספק אפשרויות תצוגה נוספות, ואינו מחליף את התאמת האתר והתוכן לשימוש בטכנולוגיות מסייעות. ההעדפה לצמצום תנועה שהוגדרה במערכת ההפעלה נתמכת גם ללא הפעלת האפשרות בתפריט.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":6,"block_type":"heading","text":"בדיקות והתאמות שבוצעו","heading_level":2,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":7,"block_type":"paragraph","text":"בוצעו בדיקות טכניות אוטומטיות ובדיקות תפעול של ניווט במקלדת, תפריטים, טופס יצירת הקשר, חלון התמונות והגדלת טקסט. תוקנו ליקויי ניגודיות ושמות נגישים של קישורים וכפתורים. נוספו תיאורים מילוליים ל־123 תמונות הגלריה על סמך בדיקה חזותית שלהן.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":8,"block_type":"heading","text":"מגבלות ידועות והמשך הבדיקה","heading_level":2,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":9,"block_type":"paragraph","text":"טרם הושלמה בדיקה מקיפה עם קוראי מסך ובכל שילובי המכשירים והדפדפנים. הבדיקות המתוארות כאן אינן כוללות בדיקה של אתרי Google Photos ו־YouTube החיצוניים שאליהם יש קישורים באתר. אם מידע או פעולה אינם נגישים לכם, פנו אלינו כדי שנוכל לבדוק את הקושי ולסייע בקבלת המידע בדרך חלופית.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":10,"block_type":"heading","text":"דיווח על בעיית נגישות","heading_level":2,"anchor_ids":["accessibility-feedback"],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":11,"block_type":"paragraph","text":"לפניות בנושא נגישות ולבקשת מידע בדרך חלופית אפשר לפנות לצוות העסק בדוא״ל roniellatours@gmail.com או בטלפון 073-3744686.","heading_level":null,"anchor_ids":[],"links":[{"text":"roniellatours@gmail.com","href":"mailto:roniellatours@gmail.com"},{"text":"073-3744686","href":"tel:0733744686"}],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":12,"block_type":"paragraph","text":"כדאי לציין את כתובת העמוד, הפעולה שניסיתם לבצע, תיאור הקושי, המכשיר והדפדפן, והטכנולוגיה המסייעת אם השתמשתם בה. אפשר לצרף דרך נוחה לחזרה אליכם. אין צורך למסור מידע רפואי.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null},{"position":13,"block_type":"paragraph","text":"הצהרה זו עודכנה בתאריך 3 בנובמבר 2026.","heading_level":null,"anchor_ids":[],"links":[],"list_ordered":null,"list_items":null,"table_caption":null,"table_rows":null}]'::jsonb;
  current_blocks jsonb;
begin
  perform 1 from public.content_pages where id=target_page for update;
  if not found then return; end if;
  select jsonb_agg(to_jsonb(b)-'page_id'-'updated_at' order by b.position)
    into current_blocks from public.content_blocks b where page_id=target_page;
  if current_blocks = replacement_blocks then return; end if;
  if current_blocks is distinct from previous_blocks then
    raise notice 'Accessibility statement has editorial changes; automatic replacement skipped.';
    return;
  end if;
  delete from public.content_blocks where page_id=target_page;
  insert into public.content_blocks(page_id,position,block_type,text,heading_level,anchor_ids,links,list_ordered,list_items,table_caption,table_rows)
    select target_page,b.position,b.block_type,b.text,b.heading_level,b.anchor_ids,b.links,b.list_ordered,b.list_items,b.table_caption,b.table_rows
    from jsonb_to_recordset(replacement_blocks) as b(position integer,block_type text,text text,heading_level smallint,anchor_ids jsonb,links jsonb,list_ordered boolean,list_items jsonb,table_caption text,table_rows jsonb);
  update public.content_pages set modification_date='2026-11-03' where id=target_page;
end $accessibility$;
